import apiClient from './apiClient';

// Types
export interface LearningGoal {
    goalId: string;
    title: string;
    description: string;
    subject: string;
    difficultyLevel: 'BEGINNER' | 'INTERMEDIATE' | 'ADVANCED';
    prerequisites: string;
    learningOutcomes: string;
    isPublished: boolean;
    instructor: {
        userId: string;
        firstName: string;
        lastName: string;
        email: string;
    };
    createdAt: string;
    updatedAt: string;
}

export interface Enrollment {
    enrollmentId: string;
    learner: {
        userId: string;
        firstName: string;
        lastName: string;
    };
    goal: LearningGoal;
    status: 'ACTIVE' | 'COMPLETED' | 'PAUSED' | 'DROPPED';
    progressPercentage: number;
    enrolledAt: string;
    completedAt?: string;
    lastAccessed?: string;
}

export interface PaginatedResponse<T> {
    content: T[];
    totalElements: number;
    totalPages: number;
    size: number;
    number: number;
}

export interface Exam {
    examId: string;
    title: string;
    description: string;
    totalQuestions: number;
    durationMinutes: number;
    status: 'DRAFT' | 'PUBLISHED' | 'ARCHIVED';
    scheduledDate: string;
    course: LearningGoal;
}

export interface ExamAttempt {
    attemptId: string;
    exam: Exam;
    score: number;
    startedAt: string;
    completedAt: string;
}

// Learner API
export const learnerAPI = {
    // Get published courses (paginated)
    getCourses: async (page = 0, size = 10): Promise<PaginatedResponse<LearningGoal>> => {
        const response = await apiClient.get(`/learner/goals?page=${page}&size=${size}`);
        return response.data;
    },

    // Get course by ID
    getCourseById: async (goalId: string): Promise<LearningGoal> => {
        const response = await apiClient.get(`/learner/goals/${goalId}`);
        return response.data;
    },

    // Get my enrollments
    getMyEnrollments: async (): Promise<Enrollment[]> => {
        const response = await apiClient.get('/learner/enrollments');
        return response.data;
    },

    // Enroll in a course
    enrollInCourse: async (goalId: string): Promise<Enrollment> => {
        const response = await apiClient.post(`/learner/enroll/${goalId}`);
        return response.data;
    },

    // Update progress
    updateProgress: async (enrollmentId: string, progress: number): Promise<Enrollment> => {
        const response = await apiClient.put(`/learner/enrollments/${enrollmentId}/progress`, { progress });
        return response.data;
    },

    // Drop enrollment
    dropEnrollment: async (enrollmentId: string): Promise<void> => {
        await apiClient.delete(`/learner/enrollments/${enrollmentId}`);
    },

    // Get Dashboard Stats (Current Course, Daily Goal, Skills)
    getDashboardStats: async (): Promise<{ currentCourse: any; dailyGoal: any; skillData: any[] }> => {
        const response = await apiClient.get('/learner/dashboard/stats');
        return response.data;
    },

    // Get Course Recommendations
    getRecommendations: async (): Promise<any[]> => {
        const response = await apiClient.get('/learner/dashboard/recommendations');
        return response.data;
    },
};

// Instructor API
export const instructorAPI = {
    // Get my courses
    getMyCourses: async (): Promise<LearningGoal[]> => {
        const response = await apiClient.get('/instructor/goals');
        return response.data;
    },

    // Create course
    createCourse: async (course: Partial<LearningGoal>): Promise<LearningGoal> => {
        const response = await apiClient.post('/instructor/goals', course);
        return response.data;
    },

    // Update course
    updateCourse: async (goalId: string, course: Partial<LearningGoal>): Promise<LearningGoal> => {
        const response = await apiClient.put(`/instructor/goals/${goalId}`, course);
        return response.data;
    },

    // Publish course
    publishCourse: async (goalId: string): Promise<LearningGoal> => {
        const response = await apiClient.post(`/instructor/goals/${goalId}/publish`);
        return response.data;
    },

    // Delete course
    deleteCourse: async (goalId: string): Promise<void> => {
        await apiClient.delete(`/instructor/goals/${goalId}`);
    },
};

// System Config Types
export interface SystemConfigData {
    configId?: string;
    adaptationSensitivity: number;
    llmTemperature: number;
    contentModel: string;
    autoRemediation: boolean;
    strictProctoring: boolean;
    appVersion: string;
    environment: string;
    region: string;
    updatedAt?: string;
}

export interface SystemStats {
    serverHealth: number;
    serverStatus: string;
    aiLatency: number;
    aiLatencyChange: string;
    activeSessions: number;
    totalLearners: number;
    totalInstructors: number;
    databaseLoad: number;
    databaseStatus: string;
    totalCourses: number;
}

export interface SystemAlert {
    id: number;
    title: string;
    message: string;
    severity: 'warning' | 'info' | 'error';
    time: string;
}

// System Config API
export const systemAPI = {
    getConfig: async (): Promise<SystemConfigData> => {
        const response = await apiClient.get('/admin/system/config');
        return response.data;
    },

    updateConfig: async (config: Partial<SystemConfigData>): Promise<SystemConfigData> => {
        const response = await apiClient.put('/admin/system/config', config);
        return response.data;
    },

    getStats: async (): Promise<SystemStats> => {
        const response = await apiClient.get('/admin/system/stats');
        return response.data;
    },

    getAlerts: async (): Promise<SystemAlert[]> => {
        const response = await apiClient.get('/admin/system/alerts');
        return response.data;
    },
};

// Admin API
export const adminAPI = {
    // Get all users
    getUsers: async (): Promise<any[]> => {
        const response = await apiClient.get('/admin/users');
        return response.data;
    },

    // Get user by ID
    getUserById: async (userId: string): Promise<any> => {
        const response = await apiClient.get(`/admin/users/${userId}`);
        return response.data;
    },

    // Update user status
    updateUserStatus: async (userId: string, isActive: boolean, isVerified: boolean): Promise<any> => {
        const response = await apiClient.put(`/admin/users/${userId}/status`, { isActive, isVerified });
        return response.data;
    },

    // Delete user
    deleteUser: async (userId: string): Promise<void> => {
        await apiClient.delete(`/admin/users/${userId}`);
    },

    // Get stats
    getStats: async (): Promise<{ totalUsers: number; learners: number; instructors: number }> => {
        const response = await apiClient.get('/admin/stats');
        return response.data;
    },
};

// Exam API
export const examAPI = {
    // Learner endpoints
    getAvailableExams: async (): Promise<Exam[]> => {
        const response = await apiClient.get('/learner/exams');
        return response.data;
    },

    startExam: async (examId: string): Promise<ExamAttempt> => {
        const response = await apiClient.post(`/learner/exams/${examId}/start`);
        return response.data;
    },

    getMyAttempts: async (): Promise<ExamAttempt[]> => {
        const response = await apiClient.get('/learner/exams/attempts');
        return response.data;
    },
};

import React, { useState, useEffect } from 'react';
import {
    Box,
    Grid,
    Card,
    CardContent,
    Typography,
    LinearProgress,
    Chip,
    Button,
    IconButton,
    useTheme,
    CircularProgress,
    Alert
} from '@mui/material';
import {
    PlayCircle,
    ChevronLeft,
    ChevronRight,
    Star,
    AccessTime,
    People,
    LocalFireDepartment,
    TrendingUp,
} from '@mui/icons-material';
import { learnerAPI } from '../api/courseAPI';

// ΓöÇΓöÇΓöÇ Interfaces ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
interface DashboardStats {
    currentCourse: {
        title: string;
        module: string;
        progress: number;
        status: string;
    };
    dailyGoal: {
        minutesToday: number;
        target: number;
        streak: number;
    };
    skillData: { label: string; value: number }[];
}

interface Recommendation {
    id: string;
    title: string;
    level: string;
    levelColor: string;
    description: string;
    duration: string;
    rating: number;
    learners: string;
}

// Fixed mock upcoming exams pending backend Exam API connection
const upcomingExams = [
    { id: 1, title: 'Advanced Java Certification', date: 'FEB 12', time: '10:00 AM - 12:00 PM', type: 'Proctored' },
    { id: 2, title: 'React Component Quiz', date: 'FEB 18', time: '2:00 PM - 3:00 PM', type: 'Open Book' },
];

const achievements = [
    { icon: '≡ƒÅå', color: '#ffb74d' },
    { icon: '≡ƒÄ»', color: '#a78bfa' },
    { icon: 'Γ£à', color: '#34d399' },
];

// ΓöÇΓöÇΓöÇ Radar Chart (SVG) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const SkillRadar: React.FC<{ isDark: boolean; skillData: { label: string; value: number }[] }> = ({ isDark, skillData }) => {
    const cx = 120, cy = 120, r = 80;
    const n = skillData.length || 1;
    const angleStep = (2 * Math.PI) / n;

    const getPoint = (i: number, scale: number) => ({
        x: cx + r * scale * Math.sin(i * angleStep),
        y: cy - r * scale * Math.cos(i * angleStep),
    });

    const gridLevels = [0.25, 0.5, 0.75, 1];
    const dataPoints = skillData.map((s, i) => getPoint(i, s.value));
    const gridColor = isDark ? 'rgba(167,139,250,0.15)' : '#e0e0e0';
    const dataFill = isDark ? 'rgba(167,139,250,0.25)' : 'rgba(124,58,237,0.15)';
    const dataStroke = isDark ? '#a78bfa' : '#7c3aed';
    const labelColor = isDark ? '#a5b4fc' : '#6b7280';

    return (
        <svg width="240" height="240" viewBox="0 0 240 240">
            {gridLevels.map((lv) => (
                <polygon key={lv} points={Array.from({ length: n }, (_, i) => {
                    const p = getPoint(i, lv);
                    return `${p.x},${p.y}`;
                }).join(' ')} fill="none" stroke={gridColor} strokeWidth="1" />
            ))}
            {skillData.map((_, i) => {
                const p = getPoint(i, 1);
                return <line key={i} x1={cx} y1={cy} x2={p.x} y2={p.y} stroke={gridColor} strokeWidth="1" />;
            })}
            <polygon points={dataPoints.map(p => `${p.x},${p.y}`).join(' ')} fill={dataFill} stroke={dataStroke} strokeWidth="2" />
            {dataPoints.map((p, i) => (
                <circle key={i} cx={p.x} cy={p.y} r="4" fill={dataStroke} />
            ))}
            {skillData.map((s, i) => {
                const p = getPoint(i, 1.22);
                return (
                    <text key={i} x={p.x} y={p.y} textAnchor="middle" dominantBaseline="central"
                        fontSize="11" fill={labelColor} fontWeight="500">{s.label}</text>
                );
            })}
        </svg>
    );
};

// ΓöÇΓöÇΓöÇ Daily Goal Ring (SVG) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const DailyGoalRing: React.FC<{ minutes: number; target: number; isDark: boolean }> = ({ minutes, target, isDark }) => {
    const pct = Math.min(minutes / target, 1);
    const r = 50, cx = 60, cy = 60;
    const circumference = 2 * Math.PI * r;
    const offset = circumference * (1 - pct);
    const trackColor = isDark ? 'rgba(167,139,250,0.15)' : '#e8e8e8';
    const ringColor = isDark ? '#34d399' : '#10b981';
    const textColor = isDark ? '#f1f0ff' : '#1e1b4b';
    const subColor = isDark ? '#a5b4fc' : '#6b7280';

    return (
        <svg width="120" height="120" viewBox="0 0 120 120">
            <circle cx={cx} cy={cy} r={r} fill="none" stroke={trackColor} strokeWidth="8" />
            <circle cx={cx} cy={cy} r={r} fill="none" stroke={ringColor} strokeWidth="8"
                strokeDasharray={circumference} strokeDashoffset={offset}
                strokeLinecap="round" transform={`rotate(-90 ${cx} ${cy})`}
                style={{ transition: 'stroke-dashoffset 0.8s ease' }} />
            <text x={cx} y={cy - 6} textAnchor="middle" fontSize="24" fontWeight="700" fill={textColor}>{minutes}</text>
            <text x={cx} y={cy + 12} textAnchor="middle" fontSize="11" fill={subColor}>mins today</text>
        </svg>
    );
};

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const LearnerDashboard: React.FC = () => {
    const theme = useTheme();
    const isDark = theme.palette.mode === 'dark';

    const [stats, setStats] = useState<DashboardStats | null>(null);
    const [recs, setRecs] = useState<Recommendation[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetchDashboardData = async () => {
            try {
                setLoading(true);
                const [dashboardStats, recommendations] = await Promise.all([
                    learnerAPI.getDashboardStats(),
                    learnerAPI.getRecommendations()
                ]);
                setStats(dashboardStats);
                setRecs(recommendations);
            } catch (err: any) {
                console.error("Failed to load dashboard data:", err);
                setError(err.response?.data?.message || err.message || 'Failed to load dashboard data');
            } finally {
                setLoading(false);
            }
        };

        fetchDashboardData();
    }, []);

    if (loading) {
        return (
            <Box sx={{ p: 3, display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh' }}>
                <CircularProgress />
            </Box>
        );
    }

    if (error) {
        return (
            <Box sx={{ p: 3 }}>
                <Alert severity="error">{error}</Alert>
            </Box>
        );
    }

    const { currentCourse, dailyGoal, skillData } = stats || {};

    return (
        <Box sx={{ p: 3, bgcolor: 'background.default', minHeight: '100vh' }}>
            {/* Header */}
            <Box sx={{ mb: 3 }}>
                <Typography variant="h4" fontWeight={700} color="text.primary">Welcome back!</Typography>
                <Typography color="text.secondary">Here's your learning progress for today.</Typography>
            </Box>

            {/* Top Row: Current Course + Daily Goal */}
            <Grid container spacing={3} sx={{ mb: 3 }}>
                {/* Current Course Card */}
                <Grid size={{ xs: 12, md: 8 }}>
                    <Card sx={{
                        background: `linear-gradient(135deg, ${isDark ? '#7c3aed' : '#6d28d9'} 0%, ${isDark ? '#4c1d95' : '#4338ca'} 100%)`,
                        color: 'white', borderRadius: 3, position: 'relative', overflow: 'hidden',
                    }}>
                        <CardContent sx={{ p: 3 }}>
                            {currentCourse && Object.keys(currentCourse).length > 0 ? (
                                <>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                        <Box>
                                            <Chip label={currentCourse.status} size="small"
                                                sx={{ bgcolor: '#10b981', color: 'white', mb: 1.5, fontWeight: 600 }} />
                                            <Typography variant="h5" fontWeight={700} sx={{ mb: 0.5 }}>{currentCourse.title}</Typography>
                                            <Typography variant="body2" sx={{ opacity: 0.85 }}>{currentCourse.module}</Typography>
                                        </Box>
                                        <IconButton sx={{ bgcolor: 'rgba(255,255,255,0.15)', color: 'white', '&:hover': { bgcolor: 'rgba(255,255,255,0.3)' } }}>
                                            <PlayCircle fontSize="large" />
                                        </IconButton>
                                    </Box>
                                    <Box sx={{ mt: 3 }}>
                                        <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
                                            <Typography variant="body2">Progress</Typography>
                                            <Typography variant="body2" fontWeight={600}>{currentCourse.progress}%</Typography>
                                        </Box>
                                        <LinearProgress variant="determinate" value={currentCourse.progress}
                                            sx={{
                                                height: 8, borderRadius: 4, bgcolor: 'rgba(255,255,255,0.2)',
                                                '& .MuiLinearProgress-bar': { bgcolor: 'white', borderRadius: 4 }
                                            }} />
                                    </Box>
                                    <Button variant="outlined" sx={{
                                        mt: 2, color: 'white', borderColor: 'rgba(255,255,255,0.5)',
                                        '&:hover': { borderColor: 'white', bgcolor: 'rgba(255,255,255,0.1)' }
                                    }}>
                                        Continue Lesson
                                    </Button>
                                </>
                            ) : (
                                <Box sx={{ py: 4, textAlign: 'center' }}>
                                    <Typography variant="h6" fontWeight={700}>No active courses</Typography>
                                    <Typography variant="body2" sx={{ opacity: 0.85, mb: 2 }}>Enroll in a course to start learning!</Typography>
                                    <Button variant="contained" sx={{ bgcolor: 'white', color: '#6d28d9', '&:hover': { bgcolor: '#f3f4f6' } }}>
                                        Browse Courses
                                    </Button>
                                </Box>
                            )}
                        </CardContent>
                    </Card>
                </Grid>

                {/* Daily Goal */}
                <Grid size={{ xs: 12, md: 4 }}>
                    <Card sx={{ borderRadius: 3, height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', py: 2 }}>
                        {dailyGoal ? (
                            <>
                                <DailyGoalRing minutes={dailyGoal.minutesToday} target={dailyGoal.target} isDark={isDark} />
                                <Typography variant="subtitle1" fontWeight={700} color="text.primary" sx={{ mt: 1 }}>Daily Goal</Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mb: 1, textAlign: 'center', px: 2 }}>
                                    {dailyGoal.minutesToday >= dailyGoal.target
                                        ? "Goal reached!"
                                        : `You're doing great! ${dailyGoal.target - dailyGoal.minutesToday} mins to go.`}
                                </Typography>
                                <Chip icon={<LocalFireDepartment sx={{ color: '#ef4444 !important' }} />}
                                    label={`${dailyGoal?.streak || 0} Day Streak`}
                                    sx={{
                                        color: isDark ? '#fca5a5' : '#ef4444',
                                        bgcolor: isDark ? 'rgba(239,68,68,0.15)' : '#fef2f2',
                                        fontWeight: 600,
                                    }} />
                            </>
                        ) : (
                            <CircularProgress />
                        )}
                        <Chip icon={<LocalFireDepartment sx={{ color: '#ef4444 !important' }} />}
                            label={`${dailyGoal.streak} Day Streak`}
                            sx={{
                                color: isDark ? '#fca5a5' : '#ef4444',
                                bgcolor: isDark ? 'rgba(239,68,68,0.15)' : '#fef2f2',
                                fontWeight: 600,
                            }} />
                    </Card>
                </Grid>
            </Grid>

            {/* Middle Row: Skill Analysis + Recommendations */}
            <Grid container spacing={3} sx={{ mb: 3 }}>
                {/* Skill Analysis */}
                <Grid size={{ xs: 12, md: 5 }}>
                    <Card sx={{ borderRadius: 3, height: '100%' }}>
                        <CardContent>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
                                <Typography variant="h6" fontWeight={700} color="text.primary">Skill Analysis</Typography>
                                <Button size="small" sx={{ textTransform: 'none' }}>View Details</Button>
                            </Box>
                            <Box sx={{ display: 'flex', justifyContent: 'center' }}>
                                {skillData ? <SkillRadar isDark={isDark} skillData={skillData} /> : <CircularProgress />}
                            </Box>
                            <Typography variant="body2" color="text.secondary" textAlign="center" sx={{ mt: 1 }}>
                                AI Analysis based on recent assessments
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>

                {/* Recommendations */}
                <Grid size={{ xs: 12, md: 7 }}>
                    <Card sx={{ borderRadius: 3, height: '100%' }}>
                        <CardContent>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                    <Typography variant="h6" fontWeight={700} color="text.primary">Recommended for You</Typography>
                                    <Chip label="AI Curated" size="small"
                                        sx={{
                                            bgcolor: isDark ? 'rgba(167,139,250,0.15)' : 'rgba(124,58,237,0.08)',
                                            color: theme.palette.primary.main,
                                            fontWeight: 600,
                                        }} />
                                </Box>
                                <Box>
                                    <IconButton size="small"><ChevronLeft /></IconButton>
                                    <IconButton size="small"><ChevronRight /></IconButton>
                                </Box>
                            </Box>
                            {recs.length > 0 ? recs.map((rec) => (
                                <Card key={rec.id} variant="outlined"
                                    sx={{
                                        mb: 2, borderRadius: 2, '&:last-child': { mb: 0 },
                                        '&:hover': { boxShadow: 2, transform: 'translateY(-1px)' },
                                        transition: 'all 0.2s ease',
                                        borderColor: theme.palette.divider,
                                    }}>
                                    <CardContent sx={{ display: 'flex', gap: 2, p: 2, '&:last-child': { pb: 2 } }}>
                                        <Box sx={{
                                            width: 80, height: 80, borderRadius: 2, flexShrink: 0,
                                            bgcolor: isDark ? 'rgba(16,185,129,0.12)' : '#ecfdf5',
                                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                                        }}>
                                            <TrendingUp sx={{ fontSize: 32, color: '#10b981' }} />
                                        </Box>
                                        <Box sx={{ flex: 1 }}>
                                            <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
                                                <Typography variant="subtitle1" fontWeight={700} color="text.primary">{rec.title}</Typography>
                                                <Chip label={rec.level} size="small"
                                                    sx={{
                                                        bgcolor: rec.levelColor + '20', color: rec.levelColor,
                                                        fontWeight: 600, fontSize: '0.7rem'
                                                    }} />
                                            </Box>
                                            <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                                                {rec.description}
                                            </Typography>
                                            <Box sx={{ display: 'flex', gap: 2, color: 'text.secondary' }}>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                                    <AccessTime sx={{ fontSize: 14 }} />
                                                    <Typography variant="caption">{rec.duration}</Typography>
                                                </Box>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                                    <Star sx={{ fontSize: 14, color: '#fbbf24' }} />
                                                    <Typography variant="caption">{rec.rating}</Typography>
                                                </Box>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                                    <People sx={{ fontSize: 14 }} />
                                                    <Typography variant="caption">{rec.learners} learners</Typography>
                                                </Box>
                                            </Box>
                                        </Box>
                                    </CardContent>
                                </Card>
                            )) : (
                                <Typography color="text.secondary" textAlign="center" py={4}>
                                    No recommendations right now. Keep learning!
                                </Typography>
                            )}
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            {/* Bottom Row: Upcoming Exams + Achievements */}
            <Grid container spacing={3}>
                <Grid size={{ xs: 12, md: 6 }}>
                    <Card sx={{ borderRadius: 3 }}>
                        <CardContent>
                            <Typography variant="h6" fontWeight={700} color="text.primary" sx={{ mb: 2 }}>Upcoming Exams</Typography>
                            {upcomingExams.map((exam) => (
                                <Box key={exam.id} sx={{
                                    display: 'flex', alignItems: 'center', gap: 2, mb: 2,
                                    '&:last-child': { mb: 0 }
                                }}>
                                    <Box sx={{
                                        width: 48, textAlign: 'center', p: 0.5, borderRadius: 1,
                                        bgcolor: isDark ? 'rgba(239,68,68,0.12)' : '#fef2f2',
                                    }}>
                                        <Typography variant="caption" color="error" fontWeight={700}>
                                            {exam.date.split(' ')[0]}
                                        </Typography>
                                        <Typography variant="h6" fontWeight={700} color="error">
                                            {exam.date.split(' ')[1]}
                                        </Typography>
                                    </Box>
                                    <Box sx={{ flex: 1 }}>
                                        <Typography variant="subtitle2" fontWeight={600} color="text.primary">{exam.title}</Typography>
                                        <Typography variant="caption" color="text.secondary">
                                            {exam.time} ΓÇó {exam.type}
                                        </Typography>
                                    </Box>
                                    <Button size="small" variant="outlined" color="success"
                                        sx={{ textTransform: 'none', fontWeight: 600 }}>Prepare</Button>
                                </Box>
                            ))}
                        </CardContent>
                    </Card>
                </Grid>

                <Grid size={{ xs: 12, md: 6 }}>
                    <Card sx={{ borderRadius: 3 }}>
                        <CardContent>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
                                <Typography variant="h6" fontWeight={700} color="text.primary">Recent Achievements</Typography>
                                <Button size="small" sx={{ textTransform: 'none' }}>View All</Button>
                            </Box>
                            <Box sx={{ display: 'flex', gap: 2 }}>
                                {achievements.map((a, i) => (
                                    <Box key={i} sx={{
                                        width: 72, height: 72, borderRadius: 2, display: 'flex',
                                        alignItems: 'center', justifyContent: 'center',
                                        bgcolor: a.color + '22', fontSize: 32,
                                    }}>
                                        {a.icon}
                                    </Box>
                                ))}
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>
        </Box>
    );
};

export default LearnerDashboard;

import React, { useState, useEffect } from 'react';
import {
    Box,
    Card,
    CardContent,
    Typography,
    Slider,
    Switch,
    Select,
    MenuItem,
    Button,
    Chip,
    Alert,
    Snackbar,
    Skeleton,
    useTheme,
} from '@mui/material';
import {
    Tune,
    Save,
    RestartAlt,
    SmartToy,
    Psychology,
    Speed,
    AutoFixHigh,
    Visibility,
} from '@mui/icons-material';
import { systemAPI, type SystemConfigData } from '../../api/courseAPI';

const AIConfiguration: React.FC = () => {
    const theme = useTheme();
    const isDark = theme.palette.mode === 'dark';

    const [config, setConfig] = useState<SystemConfigData | null>(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [snackbar, setSnackbar] = useState<{ open: boolean; message: string; severity: 'success' | 'error' }>({
        open: false, message: '', severity: 'success',
    });
    const [hasChanges, setHasChanges] = useState(false);

    useEffect(() => {
        fetchConfig();
    }, []);

    const fetchConfig = async () => {
        try {
            setLoading(true);
            setError(null);
            const data = await systemAPI.getConfig();
            setConfig(data);
            setHasChanges(false);
        } catch (err: any) {
            setError(err.response?.data?.message || 'Failed to load AI configuration');
            // Fallback defaults
            setConfig({
                adaptationSensitivity: 0.75,
                llmTemperature: 0.4,
                contentModel: 'GPT-4 (Recommended)',
                autoRemediation: true,
                strictProctoring: false,
                appVersion: 'v2.4.0-beta',
                environment: 'Production',
                region: 'us-east-1',
            });
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        if (!config) return;
        try {
            setSaving(true);
            const updated = await systemAPI.updateConfig(config);
            setConfig(updated);
            setHasChanges(false);
            setSnackbar({ open: true, message: 'AI configuration saved successfully!', severity: 'success' });
        } catch (err: any) {
            setSnackbar({ open: true, message: err.response?.data?.message || 'Failed to save configuration', severity: 'error' });
        } finally {
            setSaving(false);
        }
    };

    const handleReset = () => {
        setConfig({
            ...config!,
            adaptationSensitivity: 0.75,
            llmTemperature: 0.4,
            contentModel: 'GPT-4 (Recommended)',
            autoRemediation: true,
            strictProctoring: false,
        });
        setHasChanges(true);
    };

    const updateField = <K extends keyof SystemConfigData>(key: K, value: SystemConfigData[K]) => {
        setConfig((prev) => prev ? { ...prev, [key]: value } : prev);
        setHasChanges(true);
    };

    if (loading) {
        return (
            <Box sx={{ p: 3 }}>
                <Skeleton variant="text" width={300} height={48} />
                <Skeleton variant="text" width={400} height={24} sx={{ mb: 3 }} />
                {[1, 2, 3].map((i) => (
                    <Skeleton key={i} variant="rounded" height={200} sx={{ mb: 3, borderRadius: 3 }} />
                ))}
            </Box>
        );
    }

    return (
        <Box sx={{ p: 3, bgcolor: 'background.default', minHeight: '100vh' }}>
            {/* Header */}
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 3 }}>
                <Box>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 0.5 }}>
                        <SmartToy sx={{ fontSize: 32, color: theme.palette.primary.main }} />
                        <Typography variant="h4" fontWeight={700} color="text.primary">AI Configuration</Typography>
                    </Box>
                    <Typography color="text.secondary">
                        Fine-tune AI parameters for content generation, adaptive learning, and exam proctoring.
                    </Typography>
                </Box>
                <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button variant="outlined" startIcon={<RestartAlt />} onClick={handleReset}
                        sx={{ textTransform: 'none', borderRadius: 2, fontWeight: 600 }}>
                        Reset Defaults
                    </Button>
                    <Button variant="contained" startIcon={<Save />} onClick={handleSave}
                        disabled={!hasChanges || saving}
                        sx={{ textTransform: 'none', borderRadius: 2, fontWeight: 600 }}>
                        {saving ? 'Saving...' : 'Save Changes'}
                    </Button>
                </Box>
            </Box>

            {error && (
                <Alert severity="warning" sx={{ mb: 3, borderRadius: 2 }}>
                    {error} ΓÇö Showing default values
                </Alert>
            )}

            {hasChanges && (
                <Alert severity="info" sx={{ mb: 3, borderRadius: 2 }}>
                    You have unsaved changes. Click "Save Changes" to apply.
                </Alert>
            )}

            {config && (
                <>
                    {/* Adaptive Learning Parameters */}
                    <Card sx={{ borderRadius: 3, mb: 3 }}>
                        <CardContent sx={{ p: 3 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 3 }}>
                                <Psychology sx={{ color: theme.palette.primary.main }} />
                                <Typography variant="h6" fontWeight={700} color="text.primary">Adaptive Learning Engine</Typography>
                                <Chip label="LIVE" size="small" sx={{
                                    bgcolor: isDark ? 'rgba(52,211,153,0.12)' : '#ecfdf5',
                                    color: theme.palette.success.main, fontWeight: 700, fontSize: '0.65rem',
                                }} />
                            </Box>

                            {/* Adaptation Sensitivity */}
                            <Box sx={{ mb: 4 }}>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                                    <Box>
                                        <Typography variant="subtitle1" fontWeight={600} color="text.primary">
                                            Adaptation Sensitivity
                                        </Typography>
                                        <Typography variant="body2" color="text.secondary">
                                            Controls how quickly the difficulty adjusts based on learner errors.
                                        </Typography>
                                    </Box>
                                    <Chip label={config.adaptationSensitivity.toFixed(2)} color="primary" sx={{ fontWeight: 700 }} />
                                </Box>
                                <Slider
                                    value={config.adaptationSensitivity}
                                    onChange={(_, v) => updateField('adaptationSensitivity', v as number)}
                                    min={0} max={1} step={0.05}
                                    marks={[
                                        { value: 0, label: 'Conservative' },
                                        { value: 0.5, label: 'Balanced' },
                                        { value: 1, label: 'Aggressive' },
                                    ]}
                                    sx={{ mx: 1 }}
                                />
                            </Box>

                            {/* LLM Temperature */}
                            <Box sx={{ mb: 3 }}>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                                    <Box>
                                        <Typography variant="subtitle1" fontWeight={600} color="text.primary">
                                            LLM Temperature
                                        </Typography>
                                        <Typography variant="body2" color="text.secondary">
                                            Lower values produce more deterministic exam questions. Higher values increase creativity.
                                        </Typography>
                                    </Box>
                                    <Chip label={config.llmTemperature.toFixed(2)} color="primary" sx={{ fontWeight: 700 }} />
                                </Box>
                                <Slider
                                    value={config.llmTemperature}
                                    onChange={(_, v) => updateField('llmTemperature', v as number)}
                                    min={0} max={1} step={0.05}
                                    marks={[
                                        { value: 0, label: 'Deterministic' },
                                        { value: 0.5, label: 'Balanced' },
                                        { value: 1, label: 'Creative' },
                                    ]}
                                    sx={{ mx: 1 }}
                                />
                            </Box>
                        </CardContent>
                    </Card>

                    {/* Content Generation */}
                    <Card sx={{ borderRadius: 3, mb: 3 }}>
                        <CardContent sx={{ p: 3 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 3 }}>
                                <Speed sx={{ color: theme.palette.secondary.main }} />
                                <Typography variant="h6" fontWeight={700} color="text.primary">Content Generation</Typography>
                            </Box>

                            <Box sx={{ mb: 3 }}>
                                <Typography variant="subtitle1" fontWeight={600} color="text.primary" sx={{ mb: 1 }}>
                                    AI Model
                                </Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
                                    Select the AI model used for generating course content and exam questions.
                                </Typography>
                                <Select
                                    fullWidth
                                    value={config.contentModel}
                                    onChange={(e) => updateField('contentModel', e.target.value)}
                                    sx={{ borderRadius: 2 }}
                                >
                                    <MenuItem value="GPT-4 (Recommended)">GPT-4 (Recommended)</MenuItem>
                                    <MenuItem value="GPT-3.5 Turbo">GPT-3.5 Turbo</MenuItem>
                                    <MenuItem value="Claude 3">Claude 3</MenuItem>
                                    <MenuItem value="Gemini Pro">Gemini Pro</MenuItem>
                                </Select>
                            </Box>
                        </CardContent>
                    </Card>

                    {/* Feature Toggles */}
                    <Card sx={{ borderRadius: 3 }}>
                        <CardContent sx={{ p: 3 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 3 }}>
                                <Tune sx={{ color: theme.palette.warning.main }} />
                                <Typography variant="h6" fontWeight={700} color="text.primary">Feature Toggles</Typography>
                            </Box>

                            <Box sx={{
                                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                                p: 2, borderRadius: 2, mb: 2,
                                bgcolor: isDark ? 'rgba(167,139,250,0.04)' : 'rgba(124,58,237,0.02)',
                                border: `1px solid ${theme.palette.divider}`,
                            }}>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <AutoFixHigh sx={{ color: theme.palette.success.main }} />
                                    <Box>
                                        <Typography variant="subtitle1" fontWeight={600} color="text.primary">
                                            Auto-Remediation
                                        </Typography>
                                        <Typography variant="body2" color="text.secondary">
                                            Automatically assign remedial content when learners score below threshold.
                                        </Typography>
                                    </Box>
                                </Box>
                                <Switch
                                    checked={config.autoRemediation}
                                    onChange={(e) => updateField('autoRemediation', e.target.checked)}
                                    color="primary"
                                />
                            </Box>

                            <Box sx={{
                                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                                p: 2, borderRadius: 2,
                                bgcolor: isDark ? 'rgba(167,139,250,0.04)' : 'rgba(124,58,237,0.02)',
                                border: `1px solid ${theme.palette.divider}`,
                            }}>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Visibility sx={{ color: theme.palette.error.main }} />
                                    <Box>
                                        <Typography variant="subtitle1" fontWeight={600} color="text.primary">
                                            Strict Proctoring AI
                                        </Typography>
                                        <Typography variant="body2" color="text.secondary">
                                            Enable gaze tracking, tab switching detection, and AI-based anomaly analysis during exams.
                                        </Typography>
                                    </Box>
                                </Box>
                                <Switch
                                    checked={config.strictProctoring}
                                    onChange={(e) => updateField('strictProctoring', e.target.checked)}
                                />
                            </Box>
                        </CardContent>
                    </Card>
                </>
            )}

            <Snackbar
                open={snackbar.open}
                autoHideDuration={4000}
                onClose={() => setSnackbar((p) => ({ ...p, open: false }))}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
            >
                <Alert severity={snackbar.severity} onClose={() => setSnackbar((p) => ({ ...p, open: false }))}>
                    {snackbar.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default AIConfiguration;

import React, { useState, useEffect } from 'react';
import {
    Box,
    Card,
    CardContent,
    Typography,
    TextField,
    Button,
