                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                                <Box>
                                    <Typography variant="subtitle2" fontWeight={600} color="text.primary" sx={{ mb: 1 }}>
                                        Environment
                                    </Typography>
                                    <Select
                                        fullWidth
                                        value={config.environment}
                                        onChange={(e) => updateField('environment', e.target.value)}
                                        sx={{ borderRadius: 2 }}
