                                    <Typography variant="subtitle2" fontWeight={600} color="text.primary" sx={{ mb: 1 }}>
                                        Deployment Region
                                    </Typography>
                                    <Select
                                        fullWidth
                                        value={config.region}
                                        onChange={(e) => updateField('region', e.target.value)}
                                        sx={{ borderRadius: 2 }}
                                        startAdornment={<Public sx={{ mr: 1, color: 'text.secondary' }} />}
