                                    </Select>
                                </Box>
                            </Box>
                        </CardContent>
                    </Card>

                    {/* Security & Access */}
                    <Card sx={{ borderRadius: 3 }}>
                        <CardContent sx={{ p: 3 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 3 }}>
                                <Security sx={{ color: theme.palette.warning.main }} />
                                <Typography variant="h6" fontWeight={700} color="text.primary">Security & Access</Typography>
                            </Box>

                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                                {[
                                    { label: 'Authentication', value: 'JWT (JSON Web Token)', status: 'Active' },
                                    { label: 'Password Hashing', value: 'BCrypt (10 rounds)', status: 'Active' },
                                    { label: 'CORS Policy', value: 'Strict (whitelisted origins)', status: 'Active' },
                                    { label: 'Session Management', value: 'Stateless', status: 'Active' },
                                ].map((item, i) => (
                                    <React.Fragment key={i}>
                                        <Box sx={{
                                            display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                                            p: 2, borderRadius: 2,
                                            bgcolor: isDark ? 'rgba(167,139,250,0.04)' : 'rgba(124,58,237,0.02)',
                                        }}>
                                            <Box>
                                                <Typography variant="subtitle2" fontWeight={600} color="text.primary">
                                                    {item.label}
                                                </Typography>
                                                <Typography variant="body2" color="text.secondary">{item.value}</Typography>
                                            </Box>
                                            <Chip label={item.status} size="small" sx={{
                                                bgcolor: isDark ? 'rgba(52,211,153,0.12)' : '#ecfdf5',
                                                color: theme.palette.success.main, fontWeight: 600,
                                            }} />
                                        </Box>
                                        {i < 3 && <Divider />}
                                    </React.Fragment>
                                ))}
                            </Box>
                        </CardContent>
                    </Card>
                </>
            )}

            <Snackbar
                open={snackbar.open}
                autoHideDuration={4000}
                onClose={() => setSnackbar((p) => ({ ...p, open: false }))}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
            >
                <Alert severity={snackbar.severity} onClose={() => setSnackbar((p) => ({ ...p, open: false }))}>
                    {snackbar.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default AdminSettings;

import React, { useState, useEffect } from 'react';
import {
    Box,
    Grid,
    Card,
    CardContent,
    Typography,
    Chip,
    Button,
    Skeleton,
    Alert,
    useTheme,
} from '@mui/material';
import {
    Monitor,
    Refresh,
    Warning,
    Info,
    Error as ErrorIcon,
    Dns,
    Speed,
    People,
    Storage,
} from '@mui/icons-material';
import { systemAPI, type SystemStats, type SystemAlert } from '../../api/courseAPI';

const SystemMonitor: React.FC = () => {
    const theme = useTheme();
    const isDark = theme.palette.mode === 'dark';

    const [stats, setStats] = useState<SystemStats | null>(null);
    const [alerts, setAlerts] = useState<SystemAlert[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [lastRefresh, setLastRefresh] = useState<Date>(new Date());

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            setLoading(true);
            setError(null);
            const [statsData, alertsData] = await Promise.all([
                systemAPI.getStats(),
                systemAPI.getAlerts(),
            ]);
            setStats(statsData);
            setAlerts(alertsData);
            setLastRefresh(new Date());
        } catch (err: any) {
            setError(err.response?.data?.message || 'Failed to load system stats');
            // Fallback
            setStats({
                serverHealth: 99.98,
                serverStatus: 'Operational',
                aiLatency: 142,
                aiLatencyChange: '+12ms',
                activeSessions: 1248,
                totalLearners: 1102,
                totalInstructors: 146,
                databaseLoad: 42,
                databaseStatus: 'Stable',
                totalCourses: 6,
            });
            setAlerts([
                { id: 1, title: 'High Latency Detected', message: 'AI response time exceeded 500ms.', severity: 'warning', time: '10 minutes ago' },
                { id: 2, title: 'System Backup Completed', message: 'Daily snapshot created.', severity: 'info', time: '2 hours ago' },
            ]);
        } finally {
            setLoading(false);
        }
    };

    const alertIcons: Record<string, React.ReactNode> = {
        warning: <Warning sx={{ color: theme.palette.warning.main }} />,
        info: <Info sx={{ color: theme.palette.info.main }} />,
        error: <ErrorIcon sx={{ color: theme.palette.error.main }} />,
    };

    const alertBg: Record<string, string> = {
        warning: isDark ? 'rgba(245,158,11,0.08)' : '#fffbeb',
        info: isDark ? 'rgba(59,130,246,0.08)' : '#eff6ff',
        error: isDark ? 'rgba(239,68,68,0.08)' : '#fef2f2',
    };

    const alertTitleColor: Record<string, string> = {
        warning: isDark ? '#fbbf24' : '#b45309',
        info: isDark ? '#60a5fa' : '#1d4ed8',
        error: isDark ? '#f87171' : '#b91c1c',
    };

    if (loading) {
        return (
            <Box sx={{ p: 3 }}>
                <Skeleton variant="text" width={300} height={48} />
                <Skeleton variant="text" width={400} height={24} sx={{ mb: 3 }} />
                <Grid container spacing={2} sx={{ mb: 3 }}>
                    {[1, 2, 3, 4].map((i) => (
                        <Grid size={{ xs: 12, sm: 6, md: 3 }} key={i}>
                            <Skeleton variant="rounded" height={160} sx={{ borderRadius: 3 }} />
                        </Grid>
                    ))}
                </Grid>
                <Skeleton variant="rounded" height={300} sx={{ borderRadius: 3 }} />
            </Box>
        );
    }

    return (
        <Box sx={{ p: 3, bgcolor: 'background.default', minHeight: '100vh' }}>
            {/* Header */}
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 3 }}>
                <Box>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 0.5 }}>
                        <Monitor sx={{ fontSize: 32, color: theme.palette.primary.main }} />
                        <Typography variant="h4" fontWeight={700} color="text.primary">System Monitor</Typography>
                    </Box>
                    <Typography color="text.secondary">
                        Real-time platform health, performance metrics, and system alerts.
                    </Typography>
                </Box>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                    <Typography variant="caption" color="text.secondary">
                        Last refresh: {lastRefresh.toLocaleTimeString()}
                    </Typography>
                    <Button variant="outlined" startIcon={<Refresh />} onClick={fetchData}
                        sx={{ textTransform: 'none', borderRadius: 2, fontWeight: 600 }}>
                        Refresh
                    </Button>
                </Box>
            </Box>

            {error && (
                <Alert severity="warning" sx={{ mb: 3, borderRadius: 2 }}>
                    {error} ΓÇö Showing cached data
                </Alert>
            )}

            {stats && (
                <>
                    {/* Health Cards */}
                    <Grid container spacing={2} sx={{ mb: 3 }}>
                        {/* Server Health */}
                        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
                            <Card sx={{ borderRadius: 3 }}>
                                <CardContent>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                                        <Dns sx={{ color: theme.palette.info.main }} />
                                        <Chip label={stats.serverStatus} size="small" sx={{
                                            bgcolor: isDark ? 'rgba(52,211,153,0.12)' : '#ecfdf5',
                                            color: theme.palette.success.main, fontWeight: 600, fontSize: '0.7rem',
                                        }} />
                                    </Box>
                                    <Typography variant="h4" fontWeight={700} color="text.primary">{stats.serverHealth}%</Typography>
                                    <Typography variant="body2" color="text.secondary">Server Health</Typography>
                                    <Box sx={{ mt: 1.5, height: 6, borderRadius: 3, bgcolor: isDark ? 'rgba(167,139,250,0.1)' : '#e0e0e0' }}>
                                        <Box sx={{
                                            height: '100%', width: `${stats.serverHealth}%`,
                                            bgcolor: stats.serverHealth > 95 ? theme.palette.success.main : theme.palette.warning.main,
                                            borderRadius: 3, transition: 'width 0.5s ease',
                                        }} />
                                    </Box>
                                    <Typography variant="caption" color="text.secondary" sx={{ mt: 0.5, display: 'block' }}>
                                        Uptime last 30 days
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>

                        {/* AI Latency */}
                        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
                            <Card sx={{ borderRadius: 3 }}>
                                <CardContent>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                                        <Speed sx={{ color: theme.palette.secondary.main }} />
                                        <Chip label={stats.aiLatencyChange} size="small" sx={{
                                            bgcolor: isDark ? 'rgba(52,211,153,0.12)' : '#ecfdf5',
                                            color: theme.palette.success.main, fontWeight: 600, fontSize: '0.7rem',
                                        }} />
                                    </Box>
                                    <Typography variant="h4" fontWeight={700} color="text.primary">{stats.aiLatency}ms</Typography>
                                    <Typography variant="body2" color="text.secondary">AI Response Latency</Typography>
                                    <Box sx={{ display: 'flex', gap: 0.5, mt: 1.5, alignItems: 'flex-end' }}>
                                        {[30, 40, 45, 50, 60, 55, 70].map((h, i) => (
                                            <Box key={i} sx={{
                                                width: 18, height: h * 0.7,
                                                bgcolor: i < 4
                                                    ? (isDark ? 'rgba(167,139,250,0.2)' : '#c7d2fe')
                                                    : (isDark ? '#a78bfa' : '#7c3aed'),
                                                borderRadius: 1, transition: 'height 0.3s ease',
                                            }} />
                                        ))}
                                    </Box>
                                    <Typography variant="caption" color="text.secondary" sx={{ mt: 0.5, display: 'block' }}>
                                        Avg response time (GPT-4)
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>

                        {/* Active Sessions */}
                        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
                            <Card sx={{ borderRadius: 3 }}>
                                <CardContent>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                                        <People sx={{ color: theme.palette.success.main }} />
                                        <Chip label="Live" size="small" sx={{
                                            bgcolor: isDark ? 'rgba(52,211,153,0.12)' : '#ecfdf5',
                                            color: theme.palette.success.main, fontWeight: 600, fontSize: '0.7rem',
                                        }} />
                                    </Box>
                                    <Typography variant="h4" fontWeight={700} color="text.primary">
                                        {stats.activeSessions.toLocaleString()}
                                    </Typography>
                                    <Typography variant="body2" color="text.secondary">Active Sessions</Typography>
                                    <Box sx={{ mt: 1.5 }}>
                                        <Typography variant="body2" color="text.secondary">
                                            Learners <strong style={{ color: theme.palette.text.primary }}>{stats.totalLearners}</strong>
                                        </Typography>
                                        <Typography variant="body2" color="text.secondary">
                                            Instructors <strong style={{ color: theme.palette.text.primary }}>{stats.totalInstructors}</strong>
                                        </Typography>
                                    </Box>
                                </CardContent>
                            </Card>
                        </Grid>

                        {/* Database Load */}
                        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
                            <Card sx={{ borderRadius: 3 }}>
                                <CardContent>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                                        <Storage sx={{ color: theme.palette.primary.main }} />
                                        <Chip label={stats.databaseStatus} size="small" sx={{
                                            bgcolor: isDark ? 'rgba(52,211,153,0.12)' : '#ecfdf5',
                                            color: theme.palette.success.main, fontWeight: 600, fontSize: '0.7rem',
                                        }} />
                                    </Box>
                                    <Typography variant="h4" fontWeight={700} color="text.primary">{stats.databaseLoad}%</Typography>
                                    <Typography variant="body2" color="text.secondary">Database Load</Typography>
                                    <Box sx={{ mt: 1.5, height: 6, borderRadius: 3, bgcolor: isDark ? 'rgba(167,139,250,0.1)' : '#e0e0e0' }}>
                                        <Box sx={{
                                            height: '100%', width: `${stats.databaseLoad}%`,
                                            bgcolor: stats.databaseLoad < 60 ? theme.palette.primary.main : theme.palette.warning.main,
                                            borderRadius: 3, transition: 'width 0.5s ease',
                                        }} />
                                    </Box>
                                    <Typography variant="caption" color="text.secondary" sx={{ mt: 0.5, display: 'block' }}>
                                        PostgreSQL CPU Usage
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                    </Grid>

                    {/* Platform Overview + Alerts */}
                    <Grid container spacing={3}>
                        {/* Platform Overview */}
                        <Grid size={{ xs: 12, md: 5 }}>
                            <Card sx={{
                                borderRadius: 3, height: '100%',
                                background: isDark
                                    ? 'linear-gradient(135deg, #1e1145 0%, #0f0a2a 100%)'
                                    : 'linear-gradient(135deg, #1e1b4b 0%, #312e81 100%)',
                                color: 'white',
                            }}>
                                <CardContent sx={{ p: 3 }}>
                                    <Typography variant="h6" fontWeight={700} sx={{ mb: 3 }}>Platform Overview</Typography>
                                    {[
                                        { label: 'Total Courses', value: stats.totalCourses.toString() },
                                        { label: 'Total Users', value: (stats.totalLearners + stats.totalInstructors).toString() },
                                        { label: 'Learners', value: stats.totalLearners.toString() },
                                        { label: 'Instructors', value: stats.totalInstructors.toString() },
                                        { label: 'Active Sessions', value: stats.activeSessions.toLocaleString() },
                                    ].map((item, i) => (
                                        <Box key={i} sx={{
                                            display: 'flex', justifyContent: 'space-between', py: 1.2,
                                            borderBottom: i < 4 ? '1px solid rgba(255,255,255,0.08)' : 'none',
                                        }}>
                                            <Typography variant="body2" sx={{ opacity: 0.7 }}>{item.label}</Typography>
                                            <Typography variant="body2" fontWeight={600}>{item.value}</Typography>
                                        </Box>
                                    ))}
                                </CardContent>
                            </Card>
                        </Grid>

                        {/* Alerts */}
                        <Grid size={{ xs: 12, md: 7 }}>
                            <Card sx={{ borderRadius: 3, height: '100%' }}>
                                <CardContent sx={{ p: 3 }}>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                                        <Typography variant="h6" fontWeight={700} color="text.primary">Recent Alerts</Typography>
                                        <Chip label={`${alerts.length} alerts`} size="small" color="primary" variant="outlined" />
                                    </Box>
                                    {alerts.length === 0 ? (
                                        <Box sx={{ textAlign: 'center', py: 4 }}>
                                            <Typography variant="body1" color="text.secondary">No recent alerts Γ£à</Typography>
                                        </Box>
                                    ) : (
                                        alerts.map((alert) => (
                                            <Box key={alert.id} sx={{
                                                p: 2, borderRadius: 2, mb: 2, '&:last-child': { mb: 0 },
                                                bgcolor: alertBg[alert.severity] || alertBg.info,
                                                border: `1px solid ${isDark ? 'rgba(255,255,255,0.05)' : 'transparent'}`,
                                            }}>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                                                    {alertIcons[alert.severity]}
                                                    <Typography variant="subtitle2" fontWeight={700}
                                                        sx={{ color: alertTitleColor[alert.severity] }}>
                                                        {alert.title}
                                                    </Typography>
                                                </Box>
                                                <Typography variant="body2" color="text.secondary">{alert.message}</Typography>
                                                <Typography variant="caption"
                                                    sx={{ color: alertTitleColor[alert.severity], mt: 0.5, display: 'block' }}>
                                                    {alert.time}
                                                </Typography>
                                            </Box>
                                        ))
                                    )}
                                </CardContent>
                            </Card>
                        </Grid>
                    </Grid>
                </>
            )}
        </Box>
    );
};

export default SystemMonitor;

import React, { useState, useEffect } from 'react';
import {
    Box,
    Grid,
    Card,
    CardContent,
    Typography,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Paper,
    IconButton,
    Chip,
    Avatar,
    TextField,
    InputAdornment,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Menu,
    Alert,
    Skeleton,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    Snackbar,
} from '@mui/material';
import {
    Search,
    MoreVert,
    PersonOff,
    VerifiedUser,
    Delete,
    People,
    School,
    AdminPanelSettings,
} from '@mui/icons-material';
import { adminAPI } from '../../api/courseAPI';

interface User {
    userId: string;
    email: string;
    firstName: string;
    lastName: string;
    role: 'ADMIN' | 'INSTRUCTOR' | 'LEARNER';
    isActive: boolean;
    isVerified: boolean;
    createdAt: string;
}

const roleColors: Record<string, string> = {
    ADMIN: '#ef4444',
    INSTRUCTOR: '#f59e0b',
    LEARNER: '#10b981',
};

const roleIcons: Record<string, React.ReactElement> = {
    ADMIN: <AdminPanelSettings fontSize="small" />,
    INSTRUCTOR: <School fontSize="small" />,
    LEARNER: <People fontSize="small" />,
};

const UserManagement: React.FC = () => {
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [roleFilter, setRoleFilter] = useState<string>('ALL');
    const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
    const [selectedUser, setSelectedUser] = useState<User | null>(null);
    const [editDialogOpen, setEditDialogOpen] = useState(false);
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [snackbar, setSnackbar] = useState<{ open: boolean; message: string; severity: 'success' | 'error' }>({
        open: false,
        message: '',
        severity: 'success',
    });

    useEffect(() => {
        fetchUsers();
    }, []);

    const fetchUsers = async () => {
        try {
            setLoading(true);
            const data = await adminAPI.getUsers();
            setUsers(data);
        } catch (err: any) {
            setError('Failed to load users');
            // Mock data
            setUsers([
                { userId: '1', email: 'admin@skillforge.com', firstName: 'Admin', lastName: 'User', role: 'ADMIN', isActive: true, isVerified: true, createdAt: new Date().toISOString() },
                { userId: '2', email: 'instructor@skillforge.com', firstName: 'John', lastName: 'Instructor', role: 'INSTRUCTOR', isActive: true, isVerified: true, createdAt: new Date().toISOString() },
                { userId: '3', email: 'learner@skillforge.com', firstName: 'Jane', lastName: 'Learner', role: 'LEARNER', isActive: true, isVerified: true, createdAt: new Date().toISOString() },
                { userId: '4', email: 'new.user@example.com', firstName: 'New', lastName: 'User', role: 'LEARNER', isActive: false, isVerified: false, createdAt: new Date().toISOString() },
            ]);
        } finally {
            setLoading(false);
        }
    };

    const handleMenuOpen = (event: React.MouseEvent<HTMLElement>, user: User) => {
        setAnchorEl(event.currentTarget);
        setSelectedUser(user);
    };

    const handleMenuClose = () => {
        setAnchorEl(null);
    };

    const handleUpdateStatus = async () => {
        if (!selectedUser) return;
        try {
            await adminAPI.updateUserStatus(
                selectedUser.userId,
                !selectedUser.isActive,
                selectedUser.isVerified
            );
            setUsers((prev) =>
                prev.map((u) =>
                    u.userId === selectedUser.userId ? { ...u, isActive: !u.isActive } : u
                )
            );
            setSnackbar({ open: true, message: 'User status updated!', severity: 'success' });
        } catch {
            setSnackbar({ open: true, message: 'Failed to update user', severity: 'error' });
        }
        setEditDialogOpen(false);
        handleMenuClose();
    };

    const handleDelete = async () => {
        if (!selectedUser) return;
        try {
            await adminAPI.deleteUser(selectedUser.userId);
            setUsers((prev) => prev.filter((u) => u.userId !== selectedUser.userId));
            setSnackbar({ open: true, message: 'User deleted!', severity: 'success' });
        } catch {
            setSnackbar({ open: true, message: 'Failed to delete user', severity: 'error' });
        }
        setDeleteDialogOpen(false);
        handleMenuClose();
    };

    const filteredUsers = users.filter((user) => {
        const matchesSearch =
            user.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
            user.firstName.toLowerCase().includes(searchQuery.toLowerCase()) ||
            user.lastName.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesRole = roleFilter === 'ALL' || user.role === roleFilter;
        return matchesSearch && matchesRole;
    });

    const stats = {
        total: users.length,
        admins: users.filter((u) => u.role === 'ADMIN').length,
        instructors: users.filter((u) => u.role === 'INSTRUCTOR').length,
        learners: users.filter((u) => u.role === 'LEARNER').length,
    };

    return (
        <Box sx={{ p: 3 }}>
            {/* Header */}
            <Box sx={{ mb: 4 }}>
                <Typography variant="h4" fontWeight={700} gutterBottom>
                    User Management ≡ƒæÑ
                </Typography>
                <Typography variant="body1" color="text.secondary">
                    Manage user accounts, roles, and permissions
                </Typography>
            </Box>

            {error && (
                <Alert severity="warning" sx={{ mb: 3 }}>
                    {error} - Showing demo data
                </Alert>
            )}

            {/* Stats Cards */}
            <Grid container spacing={3} sx={{ mb: 4 }}>
                <Grid size={{ xs: 6, md: 3 }}>
                    <Card>
                        <CardContent>
                            <Typography variant="h4" fontWeight={700}>
                                {stats.total}
                            </Typography>
                            <Typography variant="body2" color="text.secondary">
                                Total Users
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid size={{ xs: 6, md: 3 }}>
                    <Card sx={{ borderLeft: `4px solid ${roleColors.ADMIN}` }}>
                        <CardContent>
                            <Typography variant="h4" fontWeight={700} color="error">
                                {stats.admins}
                            </Typography>
                            <Typography variant="body2" color="text.secondary">
                                Admins
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid size={{ xs: 6, md: 3 }}>
                    <Card sx={{ borderLeft: `4px solid ${roleColors.INSTRUCTOR}` }}>
                        <CardContent>
                            <Typography variant="h4" fontWeight={700} sx={{ color: '#f59e0b' }}>
                                {stats.instructors}
                            </Typography>
                            <Typography variant="body2" color="text.secondary">
                                Instructors
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid size={{ xs: 6, md: 3 }}>
                    <Card sx={{ borderLeft: `4px solid ${roleColors.LEARNER}` }}>
                        <CardContent>
                            <Typography variant="h4" fontWeight={700} sx={{ color: '#10b981' }}>
                                {stats.learners}
                            </Typography>
                            <Typography variant="body2" color="text.secondary">
                                Learners
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            {/* Filters */}
            <Box sx={{ display: 'flex', gap: 2, mb: 3 }}>
                <TextField
                    placeholder="Search users..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    InputProps={{
                        startAdornment: (
                            <InputAdornment position="start">
                                <Search />
                            </InputAdornment>
                        ),
                    }}
                    sx={{ flexGrow: 1, maxWidth: 400 }}
                />
                <FormControl sx={{ minWidth: 150 }}>
                    <InputLabel>Role</InputLabel>
                    <Select value={roleFilter} label="Role" onChange={(e) => setRoleFilter(e.target.value)}>
                        <MenuItem value="ALL">All Roles</MenuItem>
                        <MenuItem value="ADMIN">Admin</MenuItem>
                        <MenuItem value="INSTRUCTOR">Instructor</MenuItem>
                        <MenuItem value="LEARNER">Learner</MenuItem>
                    </Select>
                </FormControl>
            </Box>

            {/* Users Table */}
            <TableContainer component={Paper}>
                <Table>
                    <TableHead>
                        <TableRow>
                            <TableCell>User</TableCell>
                            <TableCell>Role</TableCell>
                            <TableCell>Status</TableCell>
                            <TableCell>Verified</TableCell>
                            <TableCell align="right">Actions</TableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {loading
                            ? Array.from({ length: 4 }).map((_, i) => (
                                <TableRow key={i}>
                                    <TableCell><Skeleton /></TableCell>
                                    <TableCell><Skeleton width={80} /></TableCell>
                                    <TableCell><Skeleton width={60} /></TableCell>
                                    <TableCell><Skeleton width={60} /></TableCell>
                                    <TableCell><Skeleton width={40} /></TableCell>
                                </TableRow>
                            ))
                            : filteredUsers.map((user) => (
                                <TableRow key={user.userId} hover>
                                    <TableCell>
                                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                            <Avatar sx={{ bgcolor: roleColors[user.role] }}>
                                                {user.firstName[0]}{user.lastName[0]}
                                            </Avatar>
                                            <Box>
                                                <Typography variant="subtitle2" fontWeight={600}>
                                                    {user.firstName} {user.lastName}
                                                </Typography>
                                                <Typography variant="caption" color="text.secondary">
                                                    {user.email}
                                                </Typography>
                                            </Box>
                                        </Box>
                                    </TableCell>
                                    <TableCell>
                                        <Chip
                                            icon={roleIcons[user.role]}
                                            label={user.role}
                                            size="small"
                                            sx={{
                                                backgroundColor: `${roleColors[user.role]}20`,
                                                color: roleColors[user.role],
                                            }}
                                        />
                                    </TableCell>
                                    <TableCell>
                                        <Chip
                                            label={user.isActive ? 'Active' : 'Inactive'}
                                            size="small"
                                            color={user.isActive ? 'success' : 'default'}
                                            variant={user.isActive ? 'filled' : 'outlined'}
                                        />
                                    </TableCell>
                                    <TableCell>
                                        {user.isVerified ? (
                                            <VerifiedUser color="primary" fontSize="small" />
                                        ) : (
                                            <Typography variant="caption" color="text.secondary">
                                                Pending
                                            </Typography>
                                        )}
                                    </TableCell>
                                    <TableCell align="right">
                                        <IconButton onClick={(e) => handleMenuOpen(e, user)}>
                                            <MoreVert />
                                        </IconButton>
                                    </TableCell>
                                </TableRow>
                            ))}
                    </TableBody>
                </Table>
            </TableContainer>

            {/* Actions Menu */}
            <Menu anchorEl={anchorEl} open={Boolean(anchorEl)} onClose={handleMenuClose}>
                <MenuItem onClick={() => { setEditDialogOpen(true); handleMenuClose(); }}>
                    <PersonOff sx={{ mr: 1 }} />
                    {selectedUser?.isActive ? 'Deactivate' : 'Activate'}
                </MenuItem>
                <MenuItem onClick={() => { setDeleteDialogOpen(true); handleMenuClose(); }} sx={{ color: 'error.main' }}>
                    <Delete sx={{ mr: 1 }} /> Delete
                </MenuItem>
            </Menu>

            {/* Edit Dialog */}
            <Dialog open={editDialogOpen} onClose={() => setEditDialogOpen(false)}>
                <DialogTitle>
                    {selectedUser?.isActive ? 'Deactivate' : 'Activate'} User
                </DialogTitle>
                <DialogContent>
                    <Typography>
                        Are you sure you want to {selectedUser?.isActive ? 'deactivate' : 'activate'}{' '}
                        {selectedUser?.firstName} {selectedUser?.lastName}?
                    </Typography>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setEditDialogOpen(false)}>Cancel</Button>
                    <Button onClick={handleUpdateStatus} variant="contained">
                        Confirm
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Delete Dialog */}
            <Dialog open={deleteDialogOpen} onClose={() => setDeleteDialogOpen(false)}>
                <DialogTitle>Delete User</DialogTitle>
                <DialogContent>
                    <Typography>
                        Are you sure you want to delete {selectedUser?.firstName} {selectedUser?.lastName}?
                        This action cannot be undone.
                    </Typography>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setDeleteDialogOpen(false)}>Cancel</Button>
                    <Button onClick={handleDelete} color="error" variant="contained">
                        Delete
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Snackbar */}
            <Snackbar
                open={snackbar.open}
                autoHideDuration={4000}
                onClose={() => setSnackbar({ ...snackbar, open: false })}
            >
                <Alert severity={snackbar.severity} onClose={() => setSnackbar({ ...snackbar, open: false })}>
                    {snackbar.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default UserManagement;

import React, { useState } from 'react';
import {
    Box,
    Card,
    CardContent,
    Typography,
    TextField,
    Button,
    Grid,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Chip,
    Alert,
    Snackbar,
} from '@mui/material';
import { ArrowBack, Save, Add, Close } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { instructorAPI } from '../../api/courseAPI';

const CreateCourse: React.FC = () => {
    const navigate = useNavigate();
    const [saving, setSaving] = useState(false);
    const [snackbar, setSnackbar] = useState<{ open: boolean; message: string; severity: 'success' | 'error' }>({
        open: false,
        message: '',
        severity: 'success',
    });

    const [formData, setFormData] = useState({
        title: '',
        description: '',
        subject: '',
        difficultyLevel: 'BEGINNER' as 'BEGINNER' | 'INTERMEDIATE' | 'ADVANCED',
        prerequisites: [] as string[],
        learningOutcomes: [] as string[],
    });

    const [newPrerequisite, setNewPrerequisite] = useState('');
    const [newOutcome, setNewOutcome] = useState('');

    const handleChange = (field: string, value: any) => {
        setFormData((prev) => ({ ...prev, [field]: value }));
    };

    const addPrerequisite = () => {
        if (newPrerequisite.trim()) {
            setFormData((prev) => ({
                ...prev,
                prerequisites: [...prev.prerequisites, newPrerequisite.trim()],
            }));
            setNewPrerequisite('');
        }
    };

    const removePrerequisite = (index: number) => {
        setFormData((prev) => ({
            ...prev,
            prerequisites: prev.prerequisites.filter((_, i) => i !== index),
        }));
    };

    const addOutcome = () => {
        if (newOutcome.trim()) {
            setFormData((prev) => ({
                ...prev,
                learningOutcomes: [...prev.learningOutcomes, newOutcome.trim()],
            }));
            setNewOutcome('');
        }
    };

    const removeOutcome = (index: number) => {
        setFormData((prev) => ({
            ...prev,
            learningOutcomes: prev.learningOutcomes.filter((_, i) => i !== index),
        }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!formData.title || !formData.description || !formData.subject) {
            setSnackbar({ open: true, message: 'Please fill in all required fields', severity: 'error' });
            return;
        }

        try {
            setSaving(true);
            await instructorAPI.createCourse({
                ...formData,
                prerequisites: formData.prerequisites.join('||'),
                learningOutcomes: formData.learningOutcomes.join('||'),
            });
            setSnackbar({ open: true, message: 'Course created successfully!', severity: 'success' });
            setTimeout(() => navigate('/instructor/courses'), 1500);
        } catch (err: any) {
            setSnackbar({
                open: true,
                message: err.response?.data?.message || 'Failed to create course',
                severity: 'error',
            });
        } finally {
            setSaving(false);
        }
    };

    return (
        <Box sx={{ p: 3 }}>
