            <Button startIcon={<ArrowBack />} onClick={() => navigate('/instructor/courses')} sx={{ mb: 3 }}>
                Back to Courses
            </Button>

            <Typography variant="h4" fontWeight={700} gutterBottom>
                Create New Course Γ£¿
            </Typography>
            <Typography variant="body1" color="text.secondary" sx={{ mb: 4 }}>
                Fill in the details to create a new learning goal
            </Typography>

            <form onSubmit={handleSubmit}>
                <Grid container spacing={4}>
                    {/* Main Content */}
                    <Grid size={{ xs: 12, md: 8 }}>
                        <Card>
                            <CardContent sx={{ p: 4 }}>
                                <Typography variant="h6" fontWeight={600} gutterBottom>
                                    Basic Information
                                </Typography>

                                <TextField
                                    fullWidth
                                    label="Course Title"
                                    value={formData.title}
                                    onChange={(e) => handleChange('title', e.target.value)}
                                    required
                                    sx={{ mb: 3 }}
                                    placeholder="e.g., Introduction to Machine Learning"
                                />

                                <TextField
                                    fullWidth
                                    label="Description"
                                    value={formData.description}
                                    onChange={(e) => handleChange('description', e.target.value)}
                                    required
                                    multiline
                                    rows={4}
                                    sx={{ mb: 3 }}
                                    placeholder="Describe what students will learn..."
                                />

                                <Grid container spacing={2}>
                                    <Grid size={{ xs: 12, sm: 6 }}>
                                        <TextField
                                            fullWidth
                                            label="Subject"
                                            value={formData.subject}
                                            onChange={(e) => handleChange('subject', e.target.value)}
                                            required
                                            placeholder="e.g., Computer Science"
                                        />
                                    </Grid>
                                    <Grid size={{ xs: 12, sm: 6 }}>
                                        <FormControl fullWidth>
                                            <InputLabel>Difficulty Level</InputLabel>
                                            <Select
                                                value={formData.difficultyLevel}
                                                label="Difficulty Level"
                                                onChange={(e) => handleChange('difficultyLevel', e.target.value)}
                                            >
                                                <MenuItem value="BEGINNER">Beginner</MenuItem>
                                                <MenuItem value="INTERMEDIATE">Intermediate</MenuItem>
                                                <MenuItem value="ADVANCED">Advanced</MenuItem>
                                            </Select>
                                        </FormControl>
                                    </Grid>
                                </Grid>
                            </CardContent>
                        </Card>

                        {/* Learning Outcomes */}
                        <Card sx={{ mt: 3 }}>
                            <CardContent sx={{ p: 4 }}>
                                <Typography variant="h6" fontWeight={600} gutterBottom>
                                    Learning Outcomes
                                </Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                    What will students achieve after completing this course?
                                </Typography>

                                <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        value={newOutcome}
                                        onChange={(e) => setNewOutcome(e.target.value)}
                                        placeholder="Add a learning outcome..."
                                        onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addOutcome())}
                                    />
                                    <Button variant="contained" onClick={addOutcome} startIcon={<Add />}>
                                        Add
                                    </Button>
                                </Box>

                                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                                    {formData.learningOutcomes.map((outcome, index) => (
                                        <Chip
                                            key={index}
                                            label={outcome}
                                            onDelete={() => removeOutcome(index)}
                                            deleteIcon={<Close />}
                                        />
                                    ))}
                                </Box>
                            </CardContent>
                        </Card>

                        {/* Prerequisites */}
                        <Card sx={{ mt: 3 }}>
                            <CardContent sx={{ p: 4 }}>
                                <Typography variant="h6" fontWeight={600} gutterBottom>
                                    Prerequisites (Optional)
                                </Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                    What should students know before taking this course?
                                </Typography>

                                <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        value={newPrerequisite}
                                        onChange={(e) => setNewPrerequisite(e.target.value)}
                                        placeholder="Add a prerequisite..."
                                        onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addPrerequisite())}
                                    />
                                    <Button variant="outlined" onClick={addPrerequisite} startIcon={<Add />}>
                                        Add
                                    </Button>
                                </Box>

                                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                                    {formData.prerequisites.map((prereq, index) => (
                                        <Chip
                                            key={index}
                                            label={prereq}
                                            variant="outlined"
                                            onDelete={() => removePrerequisite(index)}
                                            deleteIcon={<Close />}
                                        />
                                    ))}
                                </Box>
                            </CardContent>
                        </Card>
                    </Grid>

                    {/* Sidebar */}
                    <Grid size={{ xs: 12, md: 4 }}>
                        <Card sx={{ position: 'sticky', top: 80 }}>
                            <CardContent sx={{ p: 4 }}>
                                <Typography variant="h6" fontWeight={600} gutterBottom>
                                    Publish
                                </Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                                    Your course will be saved as a draft. You can publish it later.
                                </Typography>

                                <Button
                                    type="submit"
                                    variant="contained"
                                    size="large"
                                    fullWidth
                                    startIcon={<Save />}
                                    disabled={saving}
                                    sx={{ py: 1.5 }}
                                >
                                    {saving ? 'Saving...' : 'Save as Draft'}
                                </Button>
                            </CardContent>
                        </Card>
                    </Grid>
                </Grid>
            </form>

            {/* Snackbar */}
            <Snackbar
                open={snackbar.open}
                autoHideDuration={4000}
                onClose={() => setSnackbar({ ...snackbar, open: false })}
            >
                <Alert severity={snackbar.severity} onClose={() => setSnackbar({ ...snackbar, open: false })}>
                    {snackbar.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

