                    Discover learning goals and start your journey
                </Typography>
            </Box>

            {/* Filters */}
            <Box
                sx={{
                    display: 'flex',
                    gap: 2,
                    mb: 4,
                    flexWrap: 'wrap',
                }}
            >
                <TextField
                    placeholder="Search courses..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    InputProps={{
                        startAdornment: (
                            <InputAdornment position="start">
                                <Search />
                            </InputAdornment>
                        ),
                    }}
                    sx={{ flexGrow: 1, minWidth: 250 }}
                />
                <FormControl sx={{ minWidth: 180 }}>
                    <InputLabel>Difficulty</InputLabel>
                    <Select
                        value={difficultyFilter}
                        label="Difficulty"
                        onChange={(e) => setDifficultyFilter(e.target.value)}
                        startAdornment={<SignalCellularAlt sx={{ mr: 1, color: 'action.active' }} />}
                    >
                        <MenuItem value="ALL">All Levels</MenuItem>
                        <MenuItem value="BEGINNER">Beginner</MenuItem>
                        <MenuItem value="INTERMEDIATE">Intermediate</MenuItem>
                        <MenuItem value="ADVANCED">Advanced</MenuItem>
                    </Select>
                </FormControl>
            </Box>

            {/* Error Alert */}
            {error && (
                <Alert severity="warning" sx={{ mb: 3 }}>
                    {error} - Showing demo data
                </Alert>
            )}

            {/* Course Grid */}
            <Grid container spacing={3}>
                {loading
                    ? Array.from({ length: 6 }).map((_, index) => (
                        <Grid size={{ xs: 12, sm: 6, md: 4 }} key={index}>
                            <Card sx={{ height: '100%' }}>
                                <Skeleton variant="rectangular" height={140} />
                                <CardContent>
                                    <Skeleton variant="text" width="60%" />
                                    <Skeleton variant="text" width="100%" />
                                    <Skeleton variant="text" width="80%" />
                                </CardContent>
                            </Card>
                        </Grid>
                    ))
                    : filteredCourses.map((course) => (
                        <Grid size={{ xs: 12, sm: 6, md: 4 }} key={course.goalId}>
                            <CourseCard
                                course={course}
                                onViewDetails={() => navigate(`/learner/courses/${course.goalId}`)}
                            />
                        </Grid>
                    ))}
            </Grid>

            {/* Empty State */}
            {!loading && filteredCourses.length === 0 && (
                <Box
                    sx={{
                        textAlign: 'center',
                        py: 8,
                    }}
                >
                    <FilterList sx={{ fontSize: 64, color: 'action.disabled', mb: 2 }} />
                    <Typography variant="h6" color="text.secondary">
                        No courses found
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                        Try adjusting your filters
                    </Typography>
                </Box>
            )}

            {/* Pagination */}
            {totalPages > 1 && (
                <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
                    <Pagination
                        count={totalPages}
                        page={page}
                        onChange={(_, value) => setPage(value)}
                        color="primary"
                        size="large"
                    />
                </Box>
            )}
        </Box>
    );
};

