import React, { useState, useEffect } from 'react';
import {
    Box,
    Card,
    CardContent,
    Typography,
    Chip,
    Button,
    Grid,
    List,
    ListItem,
    ListItemIcon,
    ListItemText,
    Divider,
    Skeleton,
    Alert,
    Avatar,
    Snackbar,
} from '@mui/material';
import {
    ArrowBack,
    School,
    CheckCircle,
    PlayCircle,
    SignalCellularAlt,
    Category,
    Timer,
} from '@mui/icons-material';
import { useNavigate, useParams } from 'react-router-dom';
import { learnerAPI, type LearningGoal } from '../../api/courseAPI';

const difficultyColors: Record<string, string> = {
    BEGINNER: '#10b981',
    INTERMEDIATE: '#f59e0b',
    ADVANCED: '#ef4444',
};

const CourseDetail: React.FC = () => {
    const navigate = useNavigate();
    const { id } = useParams<{ id: string }>();
    const [course, setCourse] = useState<LearningGoal | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [enrolling, setEnrolling] = useState(false);
    const [enrolled, setEnrolled] = useState(false);
    const [snackbar, setSnackbar] = useState<{ open: boolean; message: string; severity: 'success' | 'error' }>({
        open: false,
        message: '',
        severity: 'success',
    });

    useEffect(() => {
        if (id) {
            fetchCourse();
            checkEnrollment();
        }
    }, [id]);

    const fetchCourse = async () => {
        try {
            setLoading(true);
            const data = await learnerAPI.getCourseById(id!);
            setCourse(data);
        } catch (err: any) {
            setError('Failed to load course');
            // Mock data fallback
            setCourse({
                goalId: id!,
                title: 'Introduction to Machine Learning',
                description: 'Learn the fundamentals of machine learning, including supervised and unsupervised learning algorithms. This comprehensive course covers everything from basic concepts to practical implementations.',
                subject: 'Artificial Intelligence',
                difficultyLevel: 'BEGINNER',
                prerequisites: 'Basic Python||Linear Algebra',
                learningOutcomes: 'Understand ML concepts||Implement basic algorithms||Evaluate model performance||Build real-world projects',
                isPublished: true,
                instructor: { userId: '1', firstName: 'John', lastName: 'Instructor', email: 'instructor@skillforge.com' },
                createdAt: new Date().toISOString(),
                updatedAt: new Date().toISOString(),
            });
        } finally {
            setLoading(false);
        }
    };

    const checkEnrollment = async () => {
        try {
            const enrollments = await learnerAPI.getMyEnrollments();
            setEnrolled(enrollments.some((e) => e.goal.goalId === id));
        } catch {
            // Ignore error
        }
    };

    const handleEnroll = async () => {
        try {
            setEnrolling(true);
            await learnerAPI.enrollInCourse(id!);
            setEnrolled(true);
            setSnackbar({ open: true, message: 'Successfully enrolled!', severity: 'success' });
        } catch (err: any) {
            setSnackbar({
                open: true,
                message: err.response?.data?.message || 'Failed to enroll',
                severity: 'error',
            });
        } finally {
            setEnrolling(false);
        }
    };

    const parseList = (str: string): string[] => {
        return str ? str.split('||').filter(Boolean) : [];
    };

    if (loading) {
        return (
            <Box sx={{ p: 3 }}>
                <Skeleton variant="rectangular" height={200} sx={{ borderRadius: 2, mb: 3 }} />
                <Skeleton variant="text" width="60%" height={40} />
                <Skeleton variant="text" width="100%" />
                <Skeleton variant="text" width="80%" />
            </Box>
        );
    }

    if (!course) {
        return (
            <Box sx={{ p: 3 }}>
                <Alert severity="error">Course not found</Alert>
                <Button startIcon={<ArrowBack />} onClick={() => navigate('/learner/courses')} sx={{ mt: 2 }}>
                    Back to Catalog
                </Button>
            </Box>
        );
    }

    const outcomes = parseList(course.learningOutcomes);
    const prerequisites = parseList(course.prerequisites);

    return (
        <Box sx={{ p: 3 }}>
            {/* Back Button */}
            <Button
                startIcon={<ArrowBack />}
                onClick={() => navigate('/learner/courses')}
                sx={{ mb: 3 }}
            >
                Back to Catalog
            </Button>

            {error && (
                <Alert severity="warning" sx={{ mb: 3 }}>
                    {error} - Showing demo data
                </Alert>
            )}

            <Grid container spacing={4}>
                {/* Main Content */}
                <Grid size={{ xs: 12, md: 8 }}>
                    {/* Hero Card */}
                    <Card
                        sx={{
                            background: `linear-gradient(135deg, ${difficultyColors[course.difficultyLevel]}30 0%, ${difficultyColors[course.difficultyLevel]}10 100%)`,
                            border: `1px solid ${difficultyColors[course.difficultyLevel]}40`,
                            mb: 3,
                        }}
                    >
                        <CardContent sx={{ p: 4 }}>
                            <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
                                <Chip
                                    icon={<SignalCellularAlt />}
                                    label={course.difficultyLevel}
                                    sx={{
                                        backgroundColor: `${difficultyColors[course.difficultyLevel]}20`,
                                        color: difficultyColors[course.difficultyLevel],
                                        fontWeight: 600,
                                    }}
                                />
                                <Chip icon={<Category />} label={course.subject} variant="outlined" />
                            </Box>
                            <Typography variant="h3" fontWeight={700} gutterBottom>
                                {course.title}
                            </Typography>
                            <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
                                {course.description}
                            </Typography>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                <Avatar sx={{ bgcolor: 'primary.main' }}>
                                    {course.instructor.firstName[0]}
                                </Avatar>
                                <Box>
                                    <Typography variant="subtitle2">
                                        {course.instructor.firstName} {course.instructor.lastName}
                                    </Typography>
                                    <Typography variant="caption" color="text.secondary">
                                        Instructor
                                    </Typography>
                                </Box>
                            </Box>
                        </CardContent>
                    </Card>

                    {/* Learning Outcomes */}
                    <Card sx={{ mb: 3 }}>
                        <CardContent>
                            <Typography variant="h6" fontWeight={600} gutterBottom>
                                What You'll Learn
                            </Typography>
                            <Grid container spacing={2}>
                                {outcomes.map((outcome, index) => (
                                    <Grid size={{ xs: 12, sm: 6 }} key={index}>
                                        <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1 }}>
                                            <CheckCircle color="success" fontSize="small" sx={{ mt: 0.3 }} />
                                            <Typography variant="body2">{outcome}</Typography>
                                        </Box>
                                    </Grid>
                                ))}
                            </Grid>
                        </CardContent>
                    </Card>

                    {/* Prerequisites */}
                    {prerequisites.length > 0 && (
                        <Card>
                            <CardContent>
                                <Typography variant="h6" fontWeight={600} gutterBottom>
                                    Prerequisites
                                </Typography>
                                <List disablePadding>
                                    {prerequisites.map((prereq, index) => (
                                        <ListItem key={index} disableGutters>
                                            <ListItemIcon sx={{ minWidth: 36 }}>
                                                <School color="action" fontSize="small" />
                                            </ListItemIcon>
                                            <ListItemText primary={prereq} />
                                        </ListItem>
                                    ))}
                                </List>
                            </CardContent>
                        </Card>
                    )}
                </Grid>

                {/* Sidebar */}
                <Grid size={{ xs: 12, md: 4 }}>
                    <Card sx={{ position: 'sticky', top: 80 }}>
                        <CardContent sx={{ textAlign: 'center', p: 4 }}>
                            <Box
                                sx={{
                                    width: 80,
                                    height: 80,
                                    borderRadius: 3,
                                    backgroundColor: `${difficultyColors[course.difficultyLevel]}20`,
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    margin: '0 auto 16px',
                                }}
                            >
                                <School sx={{ fontSize: 40, color: difficultyColors[course.difficultyLevel] }} />
                            </Box>

                            {enrolled ? (
                                <>
                                    <Typography variant="h6" color="success.main" fontWeight={600} gutterBottom>
                                        Γ£à You're Enrolled!
                                    </Typography>
                                    <Button
                                        variant="contained"
                                        size="large"
                                        fullWidth
                                        startIcon={<PlayCircle />}
                                        onClick={() => navigate('/learner')}
                                        sx={{ mt: 2 }}
                                    >
                                        Go to Dashboard
                                    </Button>
                                </>
                            ) : (
                                <>
                                    <Typography variant="h5" fontWeight={700} gutterBottom>
                                        Start Learning Today
                                    </Typography>
                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                                        Enroll now and begin your journey
                                    </Typography>
                                    <Button
                                        variant="contained"
                                        size="large"
                                        fullWidth
                                        onClick={handleEnroll}
                                        disabled={enrolling}
                                        sx={{ py: 1.5 }}
                                    >
                                        {enrolling ? 'Enrolling...' : 'Enroll Now'}
                                    </Button>
                                </>
                            )}

                            <Divider sx={{ my: 3 }} />

                            <Box sx={{ textAlign: 'left' }}>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
                                    <Timer fontSize="small" color="action" />
                                    <Typography variant="body2" color="text.secondary">
                                        Self-paced learning
                                    </Typography>
                                </Box>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
                                    <SignalCellularAlt fontSize="small" color="action" />
                                    <Typography variant="body2" color="text.secondary">
                                        {course.difficultyLevel.toLowerCase()} level
                                    </Typography>
                                </Box>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                    <CheckCircle fontSize="small" color="action" />
                                    <Typography variant="body2" color="text.secondary">
                                        Certificate on completion
                                    </Typography>
                                </Box>
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            {/* Snackbar */}
            <Snackbar
                open={snackbar.open}
                autoHideDuration={4000}
                onClose={() => setSnackbar({ ...snackbar, open: false })}
            >
                <Alert severity={snackbar.severity} onClose={() => setSnackbar({ ...snackbar, open: false })}>
                    {snackbar.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default CourseDetail;

import React, { useState, useEffect } from 'react';
import {
    Box,
    Typography,
    Card,
    CardContent,
    Grid,
    Button,
    Chip,
    Tabs,
    Tab,
    useTheme,
    CircularProgress,
    Alert
} from '@mui/material';
import {
    Assignment,
    Timer,
    CheckCircle,
    Cancel,
    PlayArrow,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import type { Exam, ExamAttempt } from '../../api/courseAPI';
import { examAPI } from '../../api/courseAPI';

const LearnerAssessments: React.FC = () => {
    const theme = useTheme();
    const navigate = useNavigate();
    const isDark = theme.palette.mode === 'dark';

    const [tabValue, setTabValue] = useState(0);
    const [availableExams, setAvailableExams] = useState<Exam[]>([]);
    const [myAttempts, setMyAttempts] = useState<ExamAttempt[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetchAssessmentsData = async () => {
            try {
                setLoading(true);
                const [exams, attempts] = await Promise.all([
                    examAPI.getAvailableExams(),
                    examAPI.getMyAttempts()
                ]);
                setAvailableExams(exams || []);
                setMyAttempts(attempts || []);
            } catch (err: any) {
                console.error("Failed to load assessments data:", err);
                setError(err.response?.data?.message || err.message || 'Failed to load assessments');
            } finally {
                setLoading(false);
            }
        };

        fetchAssessmentsData();
    }, []);

    const handleTabChange = (_event: React.SyntheticEvent, newValue: number) => {
        setTabValue(newValue);
    };

    if (loading) {
        return (
            <Box sx={{ p: 4, display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '60vh' }}>
                <CircularProgress />
            </Box>
        );
    }

    if (error) {
        return (
            <Box sx={{ p: 4 }}>
                <Alert severity="error">{error}</Alert>
            </Box>
        );
    }

    return (
        <Box sx={{ p: 3, bgcolor: 'background.default', minHeight: '100vh' }}>
            <Box sx={{ mb: 4 }}>
                <Typography variant="h4" fontWeight={700} color="text.primary" gutterBottom>
                    Assessments
                </Typography>
                <Typography color="text.secondary">
                    Test your knowledge and track your certification progress.
                </Typography>
            </Box>

            <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
                <Tabs value={tabValue} onChange={handleTabChange} sx={{
                    '& .MuiTab-root': { fontWeight: 600, textTransform: 'none', fontSize: '1rem' }
                }}>
                    <Tab label={`Available Exams (${availableExams.length})`} />
                    <Tab label={`My Attempts (${myAttempts.length})`} />
                </Tabs>
            </Box>

            {tabValue === 0 && (
                <Grid container spacing={3}>
                    {availableExams.length > 0 ? availableExams.map((exam) => (
                        <Grid size={{ xs: 12, md: 6, lg: 4 }} key={exam.examId}>
                            <Card sx={{
                                borderRadius: 3,
                                display: 'flex',
                                flexDirection: 'column',
                                height: '100%',
                                transition: 'transform 0.2s',
                                '&:hover': { transform: 'translateY(-4px)', boxShadow: theme.shadows[4] }
                            }}>
                                <CardContent sx={{ flexGrow: 1, p: 3 }}>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
                                        <Chip
                                            label={exam.course?.title || 'General'}
                                            size="small"
                                            sx={{ bgcolor: isDark ? 'rgba(124,58,237,0.15)' : '#ede9fe', color: '#7c3aed', fontWeight: 600 }}
                                        />
                                        <Typography variant="caption" color="text.secondary" fontWeight={600}>
                                            {exam.durationMinutes} MINS
                                        </Typography>
                                    </Box>
                                    <Typography variant="h6" fontWeight={700} gutterBottom>
                                        {exam.title}
                                    </Typography>
                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 3, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
                                        {exam.description || 'Test your proficiency in this area.'}
                                    </Typography>

                                    <Box sx={{ display: 'flex', gap: 2, mt: 'auto' }}>
                                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, color: 'text.secondary' }}>
                                            <Assignment fontSize="small" />
                                            <Typography variant="body2" fontWeight={600}>
                                                {exam.totalQuestions} Qs
                                            </Typography>
                                        </Box>
                                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, color: 'text.secondary' }}>
                                            <Timer fontSize="small" />
                                            <Typography variant="body2" fontWeight={600}>
                                                Proctored
                                            </Typography>
                                        </Box>
                                    </Box>
                                </CardContent>
                                <Box sx={{ p: 2, pt: 0 }}>
                                    <Button
                                        variant="contained"
                                        fullWidth
                                        startIcon={<PlayArrow />}
                                        onClick={() => navigate(`/learner/exams/${exam.examId}`)}
                                        sx={{
                                            bgcolor: '#7c3aed',
                                            '&:hover': { bgcolor: '#6d28d9' }
                                        }}
                                    >
                                        Start Assessment
                                    </Button>
                                </Box>
                            </Card>
                        </Grid>
                    )) : (
                        <Grid size={{ xs: 12 }}>
                            <Card sx={{ p: 5, textAlign: 'center', borderRadius: 3, bgcolor: isDark ? 'background.paper' : '#f9fafb' }}>
                                <Assignment sx={{ fontSize: 60, color: 'text.disabled', mb: 2 }} />
                                <Typography variant="h6" color="text.secondary">No exams available right now.</Typography>
                            </Card>
                        </Grid>
                    )}
                </Grid>
            )}

            {tabValue === 1 && (
                <Grid container spacing={3}>
                    {myAttempts.length > 0 ? myAttempts.map((attempt) => (
                        <Grid size={{ xs: 12, md: 6 }} key={attempt.attemptId}>
                            <Card sx={{ borderRadius: 3 }}>
                                <CardContent sx={{ p: 3, display: 'flex', alignItems: 'center', gap: 3 }}>
                                    <Box sx={{
                                        width: 80, height: 80, borderRadius: '50%',
                                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                                        bgcolor: attempt.score >= 70
                                            ? (isDark ? 'rgba(16,185,129,0.1)' : '#d1fae5')
                                            : (isDark ? 'rgba(239,68,68,0.1)' : '#fee2e2'),
                                        color: attempt.score >= 70 ? '#10b981' : '#ef4444',
                                        border: '4px solid',
                                        borderColor: attempt.score >= 70 ? 'rgba(16,185,129,0.2)' : 'rgba(239,68,68,0.2)'
                                    }}>
                                        <Typography variant="h6" fontWeight={700}>
                                            {attempt.score}%
                                        </Typography>
                                    </Box>

                                    <Box sx={{ flexGrow: 1 }}>
                                        <Typography variant="subtitle1" fontWeight={700} gutterBottom>
                                            {attempt.exam?.title || 'Unknown Exam'}
                                        </Typography>
                                        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                                            Completed on {new Date(attempt.completedAt).toLocaleDateString()}
                                        </Typography>
                                        <Box sx={{ display: 'flex', gap: 1 }}>
                                            {attempt.score >= 70 ? (
                                                <Chip size="small" icon={<CheckCircle fontSize="small" />} label="Passed" sx={{ bgcolor: '#10b981', color: 'white', fontWeight: 600 }} />
                                            ) : (
                                                <Chip size="small" icon={<Cancel fontSize="small" />} label="Failed" sx={{ bgcolor: '#ef4444', color: 'white', fontWeight: 600 }} />
                                            )}
                                        </Box>
                                    </Box>

                                    <Button variant="outlined" size="small" sx={{ borderColor: 'divider', color: 'text.secondary' }}>
                                        Review
                                    </Button>
                                </CardContent>
                            </Card>
                        </Grid>
                    )) : (
                        <Grid size={{ xs: 12 }}>
                            <Card sx={{ p: 5, textAlign: 'center', borderRadius: 3, bgcolor: isDark ? 'background.paper' : '#f9fafb' }}>
                                <Typography variant="h6" color="text.secondary">You haven't taken any exams yet.</Typography>
                                <Button variant="outlined" sx={{ mt: 2 }} onClick={() => setTabValue(0)}>Browse Exams</Button>
                            </Card>
                        </Grid>
                    )}
                </Grid>
            )}
        </Box>
    );
};

export default LearnerAssessments;

import React, { useState, useEffect } from 'react';
import {
    Box,
    Typography,
    Grid,
    Card,
    CardContent,
    LinearProgress,
    Chip,
    Avatar,
    useTheme,
    CircularProgress,
    Alert
} from '@mui/material';
import {
    MenuBook,
    EmojiEvents,
    TrendingUp,
    Schedule,
} from '@mui/icons-material';
import type { Enrollment } from '../../api/courseAPI';
import { learnerAPI } from '../../api/courseAPI';

const LearnerProgress: React.FC = () => {
    const theme = useTheme();
    const isDark = theme.palette.mode === 'dark';

    const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                setLoading(true);
                const data = await learnerAPI.getMyEnrollments();
                setEnrollments(data || []);
            } catch (err: any) {
                console.error("Failed to load progress data:", err);
                setError(err.response?.data?.message || err.message || 'Failed to load progress');
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, []);

    if (loading) {
        return (
            <Box sx={{ p: 4, display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '60vh' }}>
                <CircularProgress />
            </Box>
        );
    }

    if (error) {
        return <Box sx={{ p: 4 }}><Alert severity="error">{error}</Alert></Box>;
    }

    const completedCourses = enrollments.filter(e => e.status === 'COMPLETED').length;
    const inProgressCourses = enrollments.filter(e => e.status === 'ACTIVE').length;

    // Average progress of active courses
    const activeEnrollments = enrollments.filter(e => e.status === 'ACTIVE');
    const avgProgress = activeEnrollments.length > 0
        ? Math.round(activeEnrollments.reduce((acc, curr) => acc + curr.progressPercentage, 0) / activeEnrollments.length)
        : 0;

    return (
        <Box sx={{ p: 3, bgcolor: 'background.default', minHeight: '100vh' }}>
            <Box sx={{ mb: 4 }}>
                <Typography variant="h4" fontWeight={700} color="text.primary" gutterBottom>
                    My Progress
                </Typography>
                <Typography color="text.secondary">
                    Review your learning journey and track your completions.
                </Typography>
            </Box>

            {/* Quick Stats */}
            <Grid container spacing={3} sx={{ mb: 4 }}>
                <Grid size={{ xs: 12, sm: 4 }}>
                    <Card sx={{ borderRadius: 3, bgcolor: isDark ? 'rgba(16,185,129,0.1)' : '#ecfdf5', border: '1px solid', borderColor: 'rgba(16,185,129,0.2)', boxShadow: 'none' }}>
                        <CardContent sx={{ display: 'flex', alignItems: 'center', gap: 2, p: 3 }}>
                            <Avatar sx={{ bgcolor: '#10b981', width: 56, height: 56 }}>
                                <EmojiEvents />
                            </Avatar>
                            <Box>
                                <Typography variant="h4" fontWeight={700} color="text.primary">{completedCourses}</Typography>
                                <Typography variant="body2" color="text.secondary" fontWeight={600}>COMPLETED</Typography>
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid size={{ xs: 12, sm: 4 }}>
                    <Card sx={{ borderRadius: 3, bgcolor: isDark ? 'rgba(56,189,248,0.1)' : '#e0f2fe', border: '1px solid', borderColor: 'rgba(56,189,248,0.2)', boxShadow: 'none' }}>
                        <CardContent sx={{ display: 'flex', alignItems: 'center', gap: 2, p: 3 }}>
                            <Avatar sx={{ bgcolor: '#38bdf8', width: 56, height: 56 }}>
                                <MenuBook />
                            </Avatar>
                            <Box>
                                <Typography variant="h4" fontWeight={700} color="text.primary">{inProgressCourses}</Typography>
                                <Typography variant="body2" color="text.secondary" fontWeight={600}>IN PROGRESS</Typography>
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid size={{ xs: 12, sm: 4 }}>
                    <Card sx={{ borderRadius: 3, bgcolor: isDark ? 'rgba(139,92,246,0.1)' : '#ede9fe', border: '1px solid', borderColor: 'rgba(139,92,246,0.2)', boxShadow: 'none' }}>
                        <CardContent sx={{ display: 'flex', alignItems: 'center', gap: 2, p: 3 }}>
                            <Avatar sx={{ bgcolor: '#8b5cf6', width: 56, height: 56 }}>
                                <TrendingUp />
                            </Avatar>
                            <Box>
                                <Typography variant="h4" fontWeight={700} color="text.primary">{avgProgress}%</Typography>
                                <Typography variant="body2" color="text.secondary" fontWeight={600}>AVG PROGRESS</Typography>
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            {/* Course Progress List */}
            <Typography variant="h6" fontWeight={700} sx={{ mb: 2 }}>Detailed Course Progress</Typography>
            <Grid container spacing={3}>
                {enrollments.length > 0 ? enrollments.map((enrollment) => (
                    <Grid size={{ xs: 12 }} key={enrollment.enrollmentId}>
                        <Card sx={{ borderRadius: 3, overflow: 'visible' }}>
                            <CardContent sx={{ p: 3 }}>
                                <Grid container spacing={3} alignItems="center">
                                    <Grid size={{ xs: 12, md: 5 }}>
                                        <Typography variant="subtitle1" fontWeight={700} gutterBottom>
                                            {enrollment.goal.title}
                                        </Typography>
                                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, color: 'text.secondary' }}>
                                            <Schedule fontSize="small" />
                                            <Typography variant="body2">
                                                Enrolled: {new Date(enrollment.enrolledAt).toLocaleDateString()}
                                            </Typography>
                                        </Box>
                                    </Grid>

                                    <Grid size={{ xs: 12, md: 5 }}>
                                        <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                                            <Typography variant="body2" fontWeight={600} color="text.secondary">Progress</Typography>
                                            <Typography variant="body2" fontWeight={700} color="primary">{enrollment.progressPercentage}%</Typography>
                                        </Box>
                                        <LinearProgress
                                            variant="determinate"
                                            value={enrollment.progressPercentage}
                                            sx={{
                                                height: 10,
                                                borderRadius: 5,
                                                bgcolor: theme.palette.mode === 'dark' ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.05)',
                                                '& .MuiLinearProgress-bar': { borderRadius: 5 }
                                            }}
                                        />
                                    </Grid>

                                    <Grid size={{ xs: 12, md: 2 }} sx={{ display: 'flex', justifyContent: { xs: 'flex-start', md: 'flex-end' } }}>
                                        <Chip
                                            label={enrollment.status}
                                            color={enrollment.status === 'COMPLETED' ? 'success' : (enrollment.status === 'ACTIVE' ? 'primary' : 'default')}
                                            sx={{ fontWeight: 600 }}
                                        />
                                    </Grid>
                                </Grid>
                            </CardContent>
                        </Card>
                    </Grid>
                )) : (
                    <Grid size={{ xs: 12 }}>
                        <Card sx={{ p: 5, textAlign: 'center', borderRadius: 3, bgcolor: isDark ? 'background.paper' : '#f9fafb' }}>
                            <Typography variant="h6" color="text.secondary">You don't have any enrollments yet.</Typography>
                        </Card>
                    </Grid>
                )}
            </Grid>
        </Box>
    );
};

export default LearnerProgress;
